const sql=postgres(DB,{prepare:false,max:3});
const PUBLIC_ORIGIN='https://ronaoil.com';
const encoder=new TextEncoder();
const UUID_RE=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
