const ORIGIN_ALLOWLIST=new Set(['https://chatgpt.com','https://chat.openai.com','https://openai.com','https://platform.openai.com','https://ronaoil.com','https://www.ronaoil.com']);
const SUPPORTED_PROTOCOLS=['2025-11-25','2025-06-18','2025-03-26'];
const READ_ANNOTATIONS={readOnlyHint:true,destructiveHint:false,idempotentHint:true,openWorldHint:false};
const WRITE_ANNOTATIONS={readOnlyHint:false,destructiveHint:false,idempotentHint:true,openWorldHint:false};
const GATEWAY_FUNCTION='rona-mcp-gateway';
const COORDINATE_PILOT_BINDINGS=Object.freeze({
  'rona-mcp-operations-pilot':['OPERATIONS_DIRECTOR','AI-OPERATIONS-DIRECTOR'],
  'rona-mcp-finance-pilot':['FINANCE','AI-FINANCE'],
  'rona-mcp-legal-pilot':['LEGAL','AI-LEGAL'],
  'rona-mcp-market-analyst-pilot':['COMMERCIAL_DIRECTOR','AI-COMMERCIAL-DIRECTOR'],
  'rona-mcp-rail-logistics-pilot':['RAIL_LOGISTICS','AI-RAIL-LOGISTICS'],
});
const SEGMENT_BY_SLUG=Object.freeze({'rona-mcp-operations':'operations','rona-mcp-operations-pilot':'operations-pilot','rona-mcp-finance':'finance','rona-mcp-finance-pilot':'finance-pilot','rona-mcp-legal':'legal','rona-mcp-legal-pilot':'legal-pilot','rona-mcp-market-analyst':'market-analyst','rona-mcp-market-analyst-pilot':'market-analyst-pilot','rona-mcp-rail-logistics':'rail-logistics','rona-mcp-rail-logistics-pilot':'rail-logistics-pilot','rona-mcp-system-admin':'system-admin'});
const SLUG_BY_SEGMENT=Object.freeze(Object.fromEntries(Object.entries(SEGMENT_BY_SLUG).map(([k,v])=>[v,k])));
const AI_ROLES=Object.freeze(['OPERATIONS_DIRECTOR','FINANCE','LEGAL','MARKET_ANALYST','COMMERCIAL_DIRECTOR','RAIL_LOGISTICS','SYSTEM_ADMIN']);
const BUSINESS_ROLES=new Set(['OPERATIONS_DIRECTOR','FINANCE','LEGAL','MARKET_ANALYST','COMMERCIAL_DIRECTOR','RAIL_LOGISTICS']);
const WRITE_TOOLS=new Set(['functional_conclusion_submit','task_acknowledge','task_progress_submit','handoff_request_submit','business_change_proposal_submit','operations_internal_decision','mail_send']);
const STAFF_ROLE=Object.freeze({OPERATIONS_DIRECTOR:'OPERATIONS_DIRECTOR',FINANCE:'FINANCE',LEGAL:'LEGAL',MARKET_ANALYST:'MARKET_ANALYST',COMMERCIAL_DIRECTOR:'COMMERCIAL_DIRECTOR',RAIL_LOGISTICS:'RAIL_LOGISTICS',SYSTEM_ADMIN:'SYSTEM_ADMIN'});
const ENTITY_SCOPE=Object.freeze({
  OPERATIONS_DIRECTOR:new Set(['CLIENT','CONTRACT','APPLICATION','DEAL','DOCUMENT','PAYMENT','SHIPMENT','RAIL_DOCUMENT','PUBLICATION','TASK']),
  FINANCE:new Set(['CONTRACT','APPLICATION','DEAL','PAYMENT','TASK']),
  LEGAL:new Set(['CONTRACT','DEAL','DOCUMENT','TASK']),
  MARKET_ANALYST:new Set(['CLIENT','CONTRACT','APPLICATION','DEAL','PUBLICATION','TASK']),
  COMMERCIAL_DIRECTOR:new Set(['CLIENT','CONTRACT','APPLICATION','DEAL','PUBLICATION','TASK']),
  RAIL_LOGISTICS:new Set(['DEAL','SHIPMENT','RAIL_DOCUMENT','TASK']),
  SYSTEM_ADMIN:new Set(['TASK','SYSTEM']),
});

function publicSupabaseKey(){const legacy=Deno.env.get('SUPABASE_ANON_KEY');if(legacy)return legacy;const raw=Deno.env.get('SUPABASE_PUBLISHABLE_KEYS');if(raw){try{const p=JSON.parse(raw);if(p?.default)return p.default;}catch{}}throw new Error('SUPABASE_PUBLIC_KEY_MISSING');}
function segmentFor(slug){const seg=SEGMENT_BY_SLUG[slug];if(!seg)throw new Error('MCP_ROLE_ROUTE_INVALID');return seg;}
function baseFor(slug){return `${String(SUPA_URL).replace(/\/$/,'')}/functions/v1/${GATEWAY_FUNCTION}/${segmentFor(slug)}`;}
function mcpResource(slug){return `${baseFor(slug)}/mcp`;}
function publicBaseFor(slug){return `${PUBLIC_ORIGIN}/${segmentFor(slug)}`;}
function publicMcpResource(slug){return `${publicBaseFor(slug)}/mcp`;}
function normalizeResource(slug,value){const v=String(value||'');return v===publicMcpResource(slug)||v===mcpResource(slug)?publicMcpResource(slug):null;}
function routeContext(req){const p=new URL(req.url).pathname,marker=`/${GATEWAY_FUNCTION}/`,i=p.indexOf(marker);if(i<0)return null;const rest=p.slice(i+marker.length),slash=rest.indexOf('/'),segment=slash<0?rest:rest.slice(0,slash),slug=SLUG_BY_SEGMENT[segment];if(!slug)return null;return{slug,path:slash<0?'/':(rest.slice(slash)||'/')};}
function htmlEscape(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt',"'":'&#39;','"':'&quot;'}[c]));}
function json(body,status=200,headers={}){return new Response(JSON.stringify(body,(_k,v)=>typeof v==='bigint'?v.toString():v),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store, no-cache, must-revalidate','pragma':'no-cache','referrer-policy':'no-referrer','x-content-type-options':'nosniff',...headers}});}
function oauthJson(body,status=200){return json(body,status,{'access-control-allow-origin':'*'});}
function oauthError(error,description,status=400){return oauthJson({error,error_description:description},status);}
function rpcOk(id,result){return json({jsonrpc:'2.0',id,result});}
function rpcError(id,code,message,data){const e={code,message};if(data!==undefined)e.data=data;return json({jsonrpc:'2.0',id:id??null,error:e});}
function randomToken(bytes=32){const b=crypto.getRandomValues(new Uint8Array(bytes));let s='';for(const x of b)s+=x.toString(16).padStart(2,'0');return s;}
async function sha256Hex(v){const d=new Uint8Array(await crypto.subtle.digest('SHA-256',encoder.encode(String(v))));return[...d].map(x=>x.toString(16).padStart(2,'0')).join('');}
async function hmac(keyText,input){const key=await crypto.subtle.importKey('raw',encoder.encode(String(keyText)),{name:'HMAC',hash:'SHA-256'},false,['sign']);return new Uint8Array(await crypto.subtle.sign('HMAC',key,encoder.encode(input)));}
function b64url(bytes){let raw='';for(const b of bytes)raw+=String.fromCharCode(b);return btoa(raw).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'');}
function b64urlJson(v){return b64url(encoder.encode(JSON.stringify(v)));}
function requestIds(req){const r=req.headers.get('x-request-id')||'',c=req.headers.get('x-correlation-id')||'';return{mcpRequestId:UUID_RE.test(r)?r:crypto.randomUUID(),correlationId:UUID_RE.test(c)?c:crypto.randomUUID()};}
function readBearer(req){const h=req.headers.get('authorization')||'';return h.startsWith('Bearer ')?h.slice(7).trim():'';}
function validOrigin(req){const o=req.headers.get('origin');return!o||ORIGIN_ALLOWLIST.has(o);}
function contentLengthOk(req,max){const h=req.headers.get('content-length');return!(h&&Number(h)>max);}
async function readTextLimited(req,max){if(!contentLengthOk(req,max))throw Object.assign(new Error('REQUEST_TOO_LARGE'),{status:413});const t=await req.text();if(encoder.encode(t).length>max)throw Object.assign(new Error('REQUEST_TOO_LARGE'),{status:413});return t;}
function redirectUriAllowed(uri){try{const u=new URL(uri);if(u.protocol!=='https:'||u.username||u.password||u.hash)return false;const h=u.hostname.toLowerCase();return h==='chatgpt.com'||h.endsWith('.chatgpt.com')||h==='openai.com'||h.endsWith('.openai.com');}catch{return false;}}
function exactScope(scope){const values=new Set(String(scope||'').trim().split(/\s+/).filter(Boolean));if(!values.has('mcp:read'))return null;for(const s of values)if(!['mcp:read','mcp:coordinate','offline_access'].includes(s))return null;return ['mcp:read','mcp:coordinate','offline_access'].filter(s=>values.has(s)).join(' ');}
function scopeHas(scope,value){return new Set(String(scope||'').split(/\s+/).filter(Boolean)).has(value);}
function coordinationEnabled(cfg){const b=COORDINATE_PILOT_BINDINGS[cfg?.server_slug];return Boolean(b&&cfg?.business_role===b[0]&&cfg?.identity_id===b[1]);}
function scopeAllowed(cfg,scope){return !scopeHas(scope,'mcp:coordinate')||coordinationEnabled(cfg);}
function gatewayScopes(slug){return COORDINATE_PILOT_BINDINGS[slug]?['mcp:read','mcp:coordinate','offline_access']:['mcp:read','offline_access'];}
function safeClientSuffix(id){const s=String(id||'');return s?s.slice(-12):'';}
function tokenAudit(event,form,status=null,extra={}){console.log(JSON.stringify({event,grant_type:String(form.get('grant_type')||''),client_suffix:safeClientSuffix(form.get('client_id')),resource_present:Boolean(form.get('resource')),redirect_uri_present:Boolean(form.get('redirect_uri')),code_verifier_present:Boolean(form.get('code_verifier')),status,...extra}));}
function stableValue(v){if(Array.isArray(v))return v.map(stableValue);if(v&&typeof v==='object'){const o={};for(const k of Object.keys(v).sort())o[k]=stableValue(v[k]);return o;}return v;}
function stableStringify(v){return JSON.stringify(stableValue(v));}
function cleanText(v,max=4000){if(typeof v!=='string')return null;const s=v.trim();if(!s||s.length>max||!SAFE_TEXT_RE.test(s))return null;return s;}
function validateRefs(v){if(v===undefined)return[];if(!Array.isArray(v)||v.length>20)return null;const out=[];for(const x of v){const s=cleanText(x,200);if(!s)return null;out.push(s);}return out;}
function validateTextList(v,maxItems=20,maxLen=1000){if(!Array.isArray(v)||v.length>maxItems)return null;const out=[];for(const x of v){const s=cleanText(x,maxLen);if(!s)return null;out.push(s);}return out;}
function roleArgInjected(args){return Boolean(args&&typeof args==='object'&&!Array.isArray(args)&&['role','business_role','identity_id','ai_identity_id','functional_role','server_slug','token_id','owner_admin'].some(k=>Object.prototype.hasOwnProperty.call(args,k)));}
function roleCanUseEntity(role,type){return ENTITY_SCOPE[role]?.has(type)===true;}

async function config(boundSlug){const rows=await sql`select server_slug,app_name,business_role::text,identity_id,max_requests_per_minute,enabled from portal_private.mcp_gateway_config where server_slug=${boundSlug} limit 1`;if(rows.length!==1||!rows[0].enabled)throw new Error('MCP_CONFIG_DISABLED');return rows[0];}
async function signingKey(){const env=Deno.env.get('RONA_AI_TOKEN_SIGNING_KEY');if(env&&env.length>=32)return env;const rows=await sql`select decrypted_secret from vault.decrypted_secrets where name='rona_ai_token_signing_key_v1' limit 1`;const v=rows[0]?.decrypted_secret;if(!v||String(v).length<32)throw new Error('AI_SIGNING_KEY_UNAVAILABLE');return String(v);}
async function signDownstreamToken(cfg){const rows=await sql`select identity_id,business_role::text,status::text,credential_version,revoked_at,not_before from portal_private.ai_service_identities where identity_id=${cfg.identity_id} and business_role=${cfg.business_role}::portal_private.ai_business_role_enum limit 1`;if(rows.length!==1||rows[0].status!=='ACTIVE'||rows[0].revoked_at)throw Object.assign(new Error('AI_IDENTITY_DISABLED'),{status:503});if(rows[0].not_before&&new Date(rows[0].not_before).getTime()>Date.now())throw Object.assign(new Error('AI_IDENTITY_NOT_YET_VALID'),{status:503});const now=Math.floor(Date.now()/1000),jti=crypto.randomUUID(),header={alg:'HS256',typ:'JWT',kid:'rona-ai-v1'},payload={iss:'rona-ai-identity-broker',aud:'rona-ai-read-only',sub:String(rows[0].identity_id),role:String(rows[0].business_role),ver:Number(rows[0].credential_version),iat:now,nbf:now,exp:now+300,jti,actor_type:'AI',scope:'READ_ONLY'},unsigned=`${b64urlJson(header)}.${b64urlJson(payload)}`,sig=b64url(await hmac(await signingKey(),unsigned));return{token:`${unsigned}.${sig}`,jti};}

function protectedMetadata(slug){return{resource:publicMcpResource(slug),authorization_servers:[publicBaseFor(slug)],scopes_supported:gatewayScopes(slug),bearer_methods_supported:['header'],resource_documentation:'https://ronaoil.com'};}
function authMetadata(slug){const issuer=publicBaseFor(slug);return{issuer,authorization_endpoint:`${issuer}/authorize`,token_endpoint:`${issuer}/token`,registration_endpoint:`${issuer}/register`,revocation_endpoint:`${issuer}/revoke`,response_types_supported:['code'],grant_types_supported:['authorization_code','refresh_token'],token_endpoint_auth_methods_supported:['none'],code_challenge_methods_supported:['S256'],scopes_supported:gatewayScopes(slug),service_documentation:'https://ronaoil.com'};}
